-- Complete first-pass editorial content for Sociologia da Educação.
-- Source basis: Ramos (2018), Soares & Alves (2003), Almeida (2017).
WITH seed(discipline_name,topic_name,position,title,content) AS (VALUES ('Sociologia da Educação','Educação e sociedade',1,'Conceito central','A Sociologia da Educação estuda a educação como fenômeno social. Isso implica observar relações entre escola, família, Estado, cultura, grupos, trabalho, desigualdades e formas de participação coletiva.'),
('Sociologia da Educação','Educação e sociedade',2,'A escola como instituição social','A escola possui regras, papéis, tempos, espaços e expectativas próprias. Ao mesmo tempo, incorpora conflitos e transformações da sociedade em que está inserida.'),
('Sociologia da Educação','Educação e sociedade',3,'Educação e vida social','A educação participa da socialização e da transmissão e produção de conhecimentos e valores. Ela também pode ser analisada pelos efeitos que produz sobre trajetórias sociais.'),
('Sociologia da Educação','Educação e sociedade',4,'Exemplo para visualizar','Uma mudança nas formas de avaliação escolar não é apenas mudança técnica: pode alterar relações entre professores, estudantes e famílias e modificar o que é valorizado como aprendizagem.'),
('Sociologia da Educação','Educação e sociedade',5,'Situação para analisar','Ao estudar baixo desempenho em uma turma, não procure imediatamente uma causa individual. Observe condições de ensino, organização escolar, trajetórias, recursos, expectativas e contexto social.'),
('Sociologia da Educação','Educação e sociedade',6,'Erro comum','Explicar qualquer resultado escolar por uma única causa, como “falta de esforço” ou “problema familiar”. Fenômenos sociais têm múltiplas relações e exigem análise contextualizada.'),
('Sociologia da Educação','Educação e sociedade',7,'Aprofundamento','Ramos mostra como socialização escolar e cultura escolar ajudam a investigar questões como indisciplina, desempenho e relações entre escola e sociedade. citeturn742496search5'),
('Sociologia da Educação','Educação e sociedade',8,'Aplicação na formação','Ao observar uma escola, registre práticas institucionais e relações com o contexto externo. Pergunte o que a instituição produz, reproduz, modifica ou negocia.'),
('Sociologia da Educação','Educação e sociedade',9,'Síntese','A Sociologia da Educação amplia o olhar do indivíduo isolado para relações e instituições. O desempenho e a experiência escolar são analisados dentro de contextos sociais.'),
('Sociologia da Educação','Educação e sociedade',10,'Para revisar','Explique por que um problema escolar não deve ser interpretado somente como característica individual do estudante.'),
('Sociologia da Educação','Socialização e instituições educativas',1,'Conceito central','Socialização é o processo pelo qual os sujeitos aprendem formas de agir, interpretar e participar da vida social. Instituições educativas são espaços importantes desse processo.'),
('Sociologia da Educação','Socialização e instituições educativas',2,'Socialização escolar','A escola transmite regras, rotinas e valores, mas os estudantes não são receptores passivos: suas experiências culturais interagem com as práticas institucionais.'),
('Sociologia da Educação','Socialização e instituições educativas',3,'Cultura escolar','Ramos distingue e relaciona os conceitos de socialização escolar e cultura escolar para analisar como culturas de origem e práticas institucionais se encontram no ensino-aprendizagem. citeturn742496search5'),
('Sociologia da Educação','Socialização e instituições educativas',4,'Exemplo para visualizar','Horários, formas de participação, critérios de comportamento e modos de avaliar ensinam expectativas mesmo quando não aparecem no currículo escrito.'),
('Sociologia da Educação','Socialização e instituições educativas',5,'Situação para analisar','Uma escola valoriza determinadas formas de falar e participar e interpreta outras como falta de interesse. Analise como expectativas culturais podem influenciar a interação.'),
('Sociologia da Educação','Socialização e instituições educativas',6,'Erro comum','Pensar que socialização escolar significa apenas obedecer regras. Socialização também envolve negociação, pertencimento, conflito, identidade e participação.'),
('Sociologia da Educação','Socialização e instituições educativas',7,'Aprofundamento','A expansão da escola pública brasileira colocou o desafio de construir uma cultura escolar capaz de lidar com desigualdade e diversidade, segundo a análise de Ramos. citeturn742496search2'),
('Sociologia da Educação','Socialização e instituições educativas',8,'Aplicação na formação','Ao planejar uma prática, pense também no que ela ensina implicitamente sobre convivência, participação, autoridade e reconhecimento das diferenças.'),
('Sociologia da Educação','Socialização e instituições educativas',9,'Síntese','Instituições educativas socializam por conteúdos explícitos e por práticas cotidianas. Analisar esses processos ajuda o pedagogo a perceber dimensões pedagógicas e sociais da escola.'),
('Sociologia da Educação','Socialização e instituições educativas',10,'Para revisar','Liste três práticas escolares que ensinam regras ou valores mesmo sem aparecerem como conteúdo de uma disciplina.'),
('Sociologia da Educação','Desigualdades educacionais',1,'Conceito central','Desigualdades educacionais são diferenças sistemáticas nas oportunidades, condições, trajetórias ou resultados de aprendizagem relacionadas a características sociais, econômicas, raciais, territoriais e institucionais.'),
('Sociologia da Educação','Desigualdades educacionais',2,'Desigualdade não é apenas desempenho','Uma análise de desigualdade precisa observar acesso, permanência, condições de oferta, oportunidades de aprendizagem e resultados, não apenas médias finais.'),
('Sociologia da Educação','Desigualdades educacionais',3,'Evidências brasileiras','Estudo com dados do Saeb encontrou diferenças de desempenho segundo grupos raciais e discutiu como fatores associados à eficácia escolar não eram distribuídos de modo equitativo. citeturn742496search0turn742496search3'),
('Sociologia da Educação','Desigualdades educacionais',4,'Exemplo para visualizar','Duas escolas podem ter estudantes com perfis sociais diferentes e apresentar resultados distintos. Comparar médias sem considerar composição e contexto pode produzir interpretações equivocadas.'),
('Sociologia da Educação','Desigualdades educacionais',5,'Situação para analisar','Uma rede identifica baixo desempenho em uma região de vulnerabilidade. Analise fatores externos e escolares, evitando tratar a localização como destino inevitável.'),
('Sociologia da Educação','Desigualdades educacionais',6,'Erro comum','Confundir correlação com determinação. O fato de contexto social estar associado a resultados não significa que ele fixe de forma automática a trajetória de cada estudante.'),
('Sociologia da Educação','Desigualdades educacionais',7,'Aprofundamento','Almeida encontrou relações entre desempenho e entorno social em estudo de escolas municipais de Campinas e destacou que condições socioeconômicas podem continuar influenciando trajetórias durante a escolarização. citeturn742496search1turn742496search35'),
('Sociologia da Educação','Desigualdades educacionais',8,'Aplicação na formação','Ao analisar desigualdades, combine dados quantitativos com informações sobre contexto, práticas escolares e oportunidades efetivamente oferecidas.'),
('Sociologia da Educação','Desigualdades educacionais',9,'Síntese','Estudar desigualdades é identificar padrões sociais sem apagar diferenças individuais. O objetivo é compreender mecanismos e pensar respostas institucionais e políticas.'),
('Sociologia da Educação','Desigualdades educacionais',10,'Para revisar','Diferencie desigualdade de desempenho, desigualdade de oportunidade e desigualdade de condições educacionais.'),
('Sociologia da Educação','Escola, cultura e reprodução social',1,'Conceito central','A escola participa da cultura de uma sociedade e pode reproduzir ou transformar relações sociais. A reprodução social não significa que todos os resultados sejam determinados pela escola ou fora dela.'),
('Sociologia da Educação','Escola, cultura e reprodução social',2,'Cultura e expectativas','Currículo, linguagem, critérios de avaliação e expectativas podem valorizar certos repertórios culturais. Isso pode produzir vantagens ou dificuldades em diferentes grupos.'),
('Sociologia da Educação','Escola, cultura e reprodução social',3,'Relação escola-sociedade','A análise sociológica procura entender como práticas institucionais se articulam às estruturas sociais mais amplas, sem reduzir a escola a mero reflexo da sociedade.'),
('Sociologia da Educação','Escola, cultura e reprodução social',4,'Exemplo para visualizar','Um modo específico de falar pode ser interpretado como sinal de competência em um contexto e de inadequação em outro. O efeito depende das normas culturais e institucionais que orientam a avaliação.'),
('Sociologia da Educação','Escola, cultura e reprodução social',5,'Situação para analisar','Uma escola percebe diferenças persistentes de participação entre grupos. Examine materiais, práticas, expectativas, interação docente e formas de reconhecimento.'),
('Sociologia da Educação','Escola, cultura e reprodução social',6,'Erro comum','Usar “reprodução social” como explicação total. O conceito ajuda a investigar mecanismos de continuidade das desigualdades, mas não elimina possibilidades de mudança.'),
('Sociologia da Educação','Escola, cultura e reprodução social',7,'Aprofundamento','Ramos destaca o desafio de construir cultura escolar que valorize características individuais e sociais dos alunos e lide com desigualdade e diversidade. citeturn742496search4'),
('Sociologia da Educação','Escola, cultura e reprodução social',8,'Aplicação na formação','Pergunte quais repertórios são reconhecidos na aula, quem tem oportunidades de falar e produzir, quais critérios são usados e como diferentes estudantes recebem feedback.'),
('Sociologia da Educação','Escola, cultura e reprodução social',9,'Síntese','A escola pode reproduzir padrões sociais quando práticas e oportunidades distribuem reconhecimento de forma desigual, mas também é espaço de intervenção e transformação.'),
('Sociologia da Educação','Escola, cultura e reprodução social',10,'Para revisar','Escolha uma prática escolar e descreva como ela poderia reforçar uma desigualdade e como poderia ser reorganizada para reduzi-la.'),
('Sociologia da Educação','Educação e transformação social',1,'Conceito central','Educação pode contribuir para transformações sociais ao ampliar acesso a conhecimentos, participação, reflexão e possibilidades de atuação coletiva. Seus efeitos dependem das condições concretas em que ocorre.'),
('Sociologia da Educação','Educação e transformação social',2,'Transformação não é automática','Frequentar a escola não garante por si só transformação social. É preciso observar currículo, qualidade das oportunidades, políticas, relações institucionais e contextos sociais.'),
('Sociologia da Educação','Educação e transformação social',3,'Democratização e escola pública','Ramos relaciona a expansão da escola pública e a socialização escolar ao desafio de construir uma cultura institucional adequada à democracia, à desigualdade e à diversidade. citeturn742496search2'),
('Sociologia da Educação','Educação e transformação social',4,'Exemplo para visualizar','Um projeto escolar que amplia participação estudantil pode produzir mudanças no cotidiano da instituição, mas sua continuidade depende de regras, apoio da gestão e cultura coletiva.'),
('Sociologia da Educação','Educação e transformação social',5,'Situação para analisar','Uma escola cria um projeto participativo, mas decisões continuam centralizadas. Analise a diferença entre criar uma atividade de participação e transformar práticas institucionais.'),
('Sociologia da Educação','Educação e transformação social',6,'Erro comum','Atribuir à educação o poder de resolver isoladamente problemas sociais complexos. A escola atua em articulação com políticas e demais instituições.'),
('Sociologia da Educação','Educação e transformação social',7,'Aprofundamento','Pesquisas sobre desigualdades mostram que políticas e práticas escolares importam, mas devem ser consideradas em conjunto com condições sociais e territoriais. citeturn742496search0turn742496search1'),
('Sociologia da Educação','Educação e transformação social',8,'Aplicação na formação','Ao planejar uma ação transformadora, defina problema, público, mecanismo de mudança, evidências esperadas e condições necessárias para sustentar a iniciativa.'),
('Sociologia da Educação','Educação e transformação social',9,'Síntese','Educação pode ser espaço de transformação, mas essa possibilidade é histórica e institucional, não automática. O pedagogo precisa articular prática, contexto e políticas.'),
('Sociologia da Educação','Educação e transformação social',10,'Para revisar','Explique como uma prática escolar pode contribuir para transformação social sem supor que a escola seja capaz de resolver sozinha um problema social.'))
UPDATE public.material_sections ms
SET title=s.title,content=s.content,
section_type=CASE s.position WHEN 1 THEN 'concept' WHEN 2 THEN 'explanation' WHEN 3 THEN 'explanation' WHEN 4 THEN 'examples' WHEN 5 THEN 'examples' WHEN 6 THEN 'common_mistakes' WHEN 7 THEN 'deepening' WHEN 8 THEN 'deepening' WHEN 9 THEN 'review' ELSE 'review' END
FROM seed s,public.materials m,public.topics t,public.disciplines d
WHERE ms.material_id=m.id AND m.topic_id=t.id AND t.discipline_id=d.id
AND d.name=s.discipline_name AND t.name=s.topic_name AND ms.position=s.position;

update public.disciplines set curriculum_status='in_progress'
where name='Sociologia da Educação'
and course_id=(select id from public.courses where slug='pedagogia' limit 1);